<script setup lang="ts">
import {computed,ref} from 'vue'
import {useDb} from '../../../stores/db'
import {useSession} from '../../../stores/session'
import {StatusBadge,PreviewBanner,MoneyText} from '../../../components/shared'
import {fmtMoney} from '../../../lib/money'
const db=useDb(),session=useSession(),cash=ref(30),progressive=ref(50),contra=ref(20)
const deal=computed(()=>db.data.deals.find(d=>d.landownerOrgId===session.activePersona?.orgId))
const fund=computed(()=>db.data.funds.find(f=>f.investorOrgId===session.activePersona?.orgId))
const splitTotal=computed(()=>cash.value+progressive.value+contra.value)
</script>
<template><div class="page"><header class="page-header"><div><p class="eyebrow">Partner workspace</p><h1>My JV holding</h1><p>Only the signed deal or holding associated with your organisation is visible.</p></div><StatusBadge :label="session.activePersona?.activeRole||'partner'"/></header><PreviewBanner/><template v-if="deal"><section class="card"><h2>{{db.data.projects.find(p=>p.id===deal?.projectId)?.name}}</h2><div class="card-grid"><article><span class="source-meta">Total land consideration</span><strong class="kpi-value">{{fmtMoney(deal?.totalMinor??null)}}</strong></article><article><span class="source-meta">Contra units</span><strong class="kpi-value">{{deal?.contraUnitIds.length}}</strong><StatusBadge label="Locked from buyer sale"/></article><article><span class="source-meta">Milestones</span><strong class="kpi-value">{{deal?.milestones.length}}</strong></article></div></section><section class="card form-grid"><label>Cash %<input v-model.number="cash" type="number"></label><label>Progressive %<input v-model.number="progressive" type="number"></label><label>Contra %<input v-model.number="contra" type="number"></label><p :class="{'form-error':splitTotal!==100}" class="wide">Validation total: {{splitTotal}}%. {{splitTotal===100?'Balanced.':'The consideration split must total 100%.'}}</p></section></template><section v-if="fund" class="card"><h2>Fund partner</h2><div class="card-grid"><article><span class="source-meta">Committed</span><strong>{{fmtMoney(fund.committedMinor)}}</strong></article><article><span class="source-meta">Called</span><strong>{{fmtMoney(fund.calledMinor)}}</strong></article><article><span class="source-meta">Deployed</span><strong>{{fmtMoney(fund.deployedMinor)}}</strong></article><article><span class="source-meta">Projected profit</span><MoneyText :value="fund.projectedProfitMinor"/></article><article><span class="source-meta">Declared distribution</span><strong>{{fmtMoney(fund.declaredDistributionMinor)}}</strong></article><article><span class="source-meta">Paid cash</span><strong>{{fmtMoney(fund.paidDistributionMinor)}}</strong></article></div><p>Projected, declared and paid are separate. Funding deposits are not revenue and no return is guaranteed.</p></section></div></template>
